ProxyLife* MakeProxy(REFIID iid, void* object, IUnknown* owner) {
    if (iid == __uuidof(IDirect3D9)) return new Proxy_IDirect3D9(static_cast<IDirect3D9*>(object), owner);
    if (iid == __uuidof(IDirect3DVolume9)) return new Proxy_IDirect3DVolume9(static_cast<IDirect3DVolume9*>(object), owner);
    if (iid == __uuidof(IDirect3DSwapChain9)) return new Proxy_IDirect3DSwapChain9(static_cast<IDirect3DSwapChain9*>(object), owner);
    if (iid == __uuidof(IDirect3DResource9)) return new Proxy_IDirect3DResource9(static_cast<IDirect3DResource9*>(object), owner);
    if (iid == __uuidof(IDirect3DSurface9)) return new Proxy_IDirect3DSurface9(static_cast<IDirect3DSurface9*>(object), owner);
    if (iid == __uuidof(IDirect3DVertexBuffer9)) return new Proxy_IDirect3DVertexBuffer9(static_cast<IDirect3DVertexBuffer9*>(object), owner);
    if (iid == __uuidof(IDirect3DIndexBuffer9)) return new Proxy_IDirect3DIndexBuffer9(static_cast<IDirect3DIndexBuffer9*>(object), owner);
    if (iid == __uuidof(IDirect3DBaseTexture9)) return new Proxy_IDirect3DBaseTexture9(static_cast<IDirect3DBaseTexture9*>(object), owner);
    if (iid == __uuidof(IDirect3DCubeTexture9)) return new Proxy_IDirect3DCubeTexture9(static_cast<IDirect3DCubeTexture9*>(object), owner);
    if (iid == __uuidof(IDirect3DTexture9)) return new Proxy_IDirect3DTexture9(static_cast<IDirect3DTexture9*>(object), owner);
    if (iid == __uuidof(IDirect3DVolumeTexture9)) return new Proxy_IDirect3DVolumeTexture9(static_cast<IDirect3DVolumeTexture9*>(object), owner);
    if (iid == __uuidof(IDirect3DVertexDeclaration9)) return new Proxy_IDirect3DVertexDeclaration9(static_cast<IDirect3DVertexDeclaration9*>(object), owner);
    if (iid == __uuidof(IDirect3DVertexShader9)) return new Proxy_IDirect3DVertexShader9(static_cast<IDirect3DVertexShader9*>(object), owner);
    if (iid == __uuidof(IDirect3DPixelShader9)) return new Proxy_IDirect3DPixelShader9(static_cast<IDirect3DPixelShader9*>(object), owner);
    if (iid == __uuidof(IDirect3DStateBlock9)) return new Proxy_IDirect3DStateBlock9(static_cast<IDirect3DStateBlock9*>(object), owner);
    if (iid == __uuidof(IDirect3DQuery9)) return new Proxy_IDirect3DQuery9(static_cast<IDirect3DQuery9*>(object), owner);
    if (iid == __uuidof(IDirect3DDevice9)) return new Proxy_IDirect3DDevice9(static_cast<IDirect3DDevice9*>(object), owner);
    if (iid == __uuidof(IDirect3D9Ex)) return new Proxy_IDirect3D9Ex(static_cast<IDirect3D9Ex*>(object), owner);
    if (iid == __uuidof(IDirect3DSwapChain9Ex)) return new Proxy_IDirect3DSwapChain9Ex(static_cast<IDirect3DSwapChain9Ex*>(object), owner);
    if (iid == __uuidof(IDirect3DDevice9Ex)) return new Proxy_IDirect3DDevice9Ex(static_cast<IDirect3DDevice9Ex*>(object), owner);
    return nullptr;
}
